// Handshake de verificação exigido pela Meta ao cadastrar o webhook.
const query = $('1a - Webhook Verificacao (GET)').item.json.query || {};

// A Meta manda os parâmetros com ponto; o n8n também expõe com underscore.
// Aceita as duas grafias para evitar falha de resolução de chave.
const mode = query['hub.mode'] || query['hub_mode'];
const token = query['hub.verify_token'] || query['hub_verify_token'];
const challenge = query['hub.challenge'] || query['hub_challenge'];

const tokenEsperado = $('1b - Buscar Verify Token').item.json.signing_secret;

const valido = (mode === 'subscribe' && token === tokenEsperado);

return {
  json: {
    verificacao_valida: valido,
    challenge: valido ? String(challenge) : 'forbidden'
  }
};

// Valida a assinatura HMAC-SHA256 enviada pela Meta no header X-Hub-Signature-256
// Formato do header: sha256=<hash hexadecimal>

const crypto = require('crypto');

const webhookItem = $('2 - Webhook Eventos (POST)').item.json;
const headers = webhookItem.headers || {};
const assinaturaRecebida = headers['x-hub-signature-256'] || '';

// App Secret lido do Google Sheets (nó 3), não hardcoded
const appSecret = $('3 - Buscar App Secret').item.json.signing_secret;

// A Meta assina o corpo BRUTO da requisição
const rawBody = typeof webhookItem.body === 'string'
  ? webhookItem.body
  : JSON.stringify(webhookItem.body);

let assinaturaValida = false;

try {
  const hashEsperado = 'sha256=' + crypto
    .createHmac('sha256', appSecret)
    .update(rawBody, 'utf8')
    .digest('hex');

  // Comparação em tempo constante evita timing attacks
  const a = Buffer.from(assinaturaRecebida);
  const b = Buffer.from(hashEsperado);
  assinaturaValida = a.length === b.length && crypto.timingSafeEqual(a, b);
} catch (e) {
  assinaturaValida = false;
}

// Normaliza o corpo para objeto, independente de ter chegado como string
const corpo = typeof webhookItem.body === 'string'
  ? JSON.parse(webhookItem.body)
  : webhookItem.body;

return {
  json: {
    assinatura_valida: assinaturaValida,
    corpo: corpo
  }
};

// A Meta envia os eventos aninhados em entry[].changes[].value.statuses[]
// Um único POST pode conter VÁRIOS eventos de status — por isso explodimos em itens.

const corpo = $input.item.json.corpo || {};
const saida = [];

const entries = corpo.entry || [];

for (const entry of entries) {
  const changes = entry.changes || [];
  for (const change of changes) {
    const value = change.value || {};
    const statuses = value.statuses || [];

    for (const st of statuses) {
      // Converte epoch (segundos) para ISO
      const ts = st.timestamp
        ? new Date(parseInt(st.timestamp) * 1000).toISOString()
        : '';

      // Erros só existem quando status = failed
      const erro = (st.errors && st.errors[0]) || {};

      saida.push({
        json: {
          message_id: st.id || '',
          telefone: st.recipient_id || '',
          evento: st.status || '',
          timestamp: ts,
          erro_codigo: erro.code ? String(erro.code) : '',
          erro_titulo: erro.title || '',
          erro_detalhe: (erro.error_data && erro.error_data.details) || erro.message || '',
          conversa_tipo: (st.conversation && st.conversation.origin && st.conversation.origin.type) || '',
          cobravel: st.pricing ? String(st.pricing.billable) : ''
        }
      });
    }
  }
}

return saida;

const corpo = $('4 - Valida Assinatura Meta').item.json.corpo || {};
const saida = [];
const entries = corpo.entry || [];

for (const entry of entries) {
  const changes = entry.changes || [];
  for (const change of changes) {
    const value = change.value || {};
    const messages = value.messages || [];
    for (const msg of messages) {
      const texto = (msg.text && msg.text.body) || '';
      saida.push({
        json: {
          message_id: msg.id || '',
          telefone: msg.from || '',
          texto: texto,
          timestamp: msg.timestamp
            ? new Date(parseInt(msg.timestamp) * 1000).toISOString()
            : new Date().toISOString()
        }
      });
    }
  }
}

return saida;

const KEYWORDS = ['SAIR', 'PARAR', 'CANCELAR'];

function normaliza(str) {
  return String(str || '')
    .normalize('NFD').replace(/[̀-ͯ]/g, '') // remove acentos (marcas diacriticas)
    .toUpperCase()
    .replace(/\s+/g, ' ')
    .trim();
}

function soDigitos(str) {
  return String(str || '').replace(/\D/g, '');
}

// Referências explícitas aos nós de origem -- 12 fica logo após o branch de
// 9a_if_tipo_evento, então $json cru não é confiável aqui.
const mensagens = $('10 - Extrai Mensagens Recebidas').all().map(i => i.json);
const leads = $('11 - Busca Base Funil').all().map(i => i.json);

const leads_para_atualizar = [];
const log_entries = [];
const notif_entries = [];

for (const msg of mensagens) {
  const textoNorm = normaliza(msg.texto);
  const ehOptout = KEYWORDS.some(k => textoNorm.includes(k));

  const telefoneMsg = soDigitos(msg.telefone);
  const leadsEncontrados = leads.filter(l => soDigitos(l.telefone) === telefoneMsg && telefoneMsg !== '');

  let acao;
  if (ehOptout && leadsEncontrados.length > 0) {
    acao = 'opt-out aplicado';
    for (const lead of leadsEncontrados) {
      leads_para_atualizar.push({
        lead_id: lead.lead_id,
        telefone: msg.telefone
      });
    }
  } else if (ehOptout && leadsEncontrados.length === 0) {
    acao = 'nao encontrado';
  } else {
    acao = 'sem acao';
  }

  const nomes = leadsEncontrados
    .map(l => l.nome_contato || l.razao_social || '')
    .filter(Boolean)
    .join(', ');

  log_entries.push({
    timestamp: msg.timestamp,
    telefone: msg.telefone,
    texto_recebido: msg.texto,
    acao_tomada: acao,
    lead_encontrado: leadsEncontrados.length > 0,
    lead_nome: nomes
  });

  notif_entries.push({
    telefone: msg.telefone,
    texto: msg.texto,
    eh_optout: ehOptout,
    acao: acao,
    lead_nome: nomes || null,
    lead_encontrado: leadsEncontrados.length > 0
  });
}

return [{
  json: { leads_para_atualizar, log_entries, notif_entries }
}];

